-- APPLICERAD I TRE DELAR. Databasen har fyra poster för det här arbetet:
--   20260912141059  elektro_order_code_structure_from_catalogue
--   20260912141330  elektro_rules_part1_sizes_32_50_63
--   20260912141406  elektro_rules_part2_sizes_h63_80_100
--   20260912141454  elektro_rules_part3_and_product_specs
-- plus 20260912141126 tmp_config_rules_loader, en tillfällig laddfunktion som
-- är SLÄPPT och kontrollerad borta. Uppdelningen var praktisk, inte semantisk:
-- regeluppsättningen är 17 kB JSON och gick inte i ett stycke. Den här filen
-- är generatorns kanoniska utdata och ger samma sluttillstånd om den körs om.
--
-- ELEKTRO ISO 15552: beställnyckeln enligt Metal Work Electric Cylinder Series ELEKTRO ISO 15552,
-- metalwork-ELEKTRO.pdf avsnitt A5.4–A5.33, utgåva EN 0224.
-- GENERERAD ur src/lib/catalog/elektro.ts -- redigera inte för hand.
--
-- DEN HÄR FAMILJEN STOD SOM BLOCKERAD. Den var det aldrig: jag hade sökt på
-- strängen "ELEKTRO", som bara står i sidhuvudet, fått två träffar och skrivit
-- av källan som tunn. Nyckeln låg i stycke 101-109 hela tiden.
--
-- Rättar sex fel:
--   1. order_code_template var 'Elektro-{size}-{stroke_mm}-{motor_mount}', som
--      ger "Elektro-32-500-inline". Metal Works kod är POSITIONELL:
--      "371032050015" -- tolv tecken utan motor, sexton med.
--   2. Storlekslistan hade 32, 40, 50, 63, 80, 100. Ø40 FINNS INTE i serien,
--      och Ø63 Heavy Duty -- som har en egen storlekskod, H63 -- saknades.
--   3. 'lead' hade koderna low/standard/high. Katalogen har åtta NUMRERADE
--      stigningar: 4, 5, 10, 12, 16, 20, 32 och 40 mm, med koderna 1, 2, 4, 5,
--      6, 7, 8, 9. Ingen av de tre gamla koderna finns i nyckeln.
--   4. 'motor_mount' hade inline/parallel. Direktkopplad och kuggremsdriven är
--      inte ett eget fält utan en del av VERSIONEN (1-4 mot 5-8), tillsammans
--      med vridningsskydd och kapslingsklass.
--   5. stroke_min_mm var 1 och stroke_max_mm 1500 för alla storlekar. Ø32
--      slutar vid 1370. Och undre gränsen är inte 1 utan antingen 80/125 mm
--      (utan vridningsskydd, "in order to re-grease the screw") eller två
--      gånger skruvstigningen (med).
--   6. Nyckelns fyra motorpositioner -- motor, fläns, moment, drivning --
--      saknades helt. Utan dem går det inte att beställa en cylinder med motor.
--
-- VAD SOM INTE GÅR ATT HÄRLEDA: drivgruppens fjärde tecken. Katalogen säger
-- att E "identifierar konfiguration med Delta BRUSHLESS-motorer", men
-- 37M2770000 ÄR en Delta och står ändå som "2770". Regeln stämmer inte, så
-- tabellen skrivs av i stället för att räknas ut.

begin;

create schema if not exists backup;
create table if not exists backup.elektro_before_20260912 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'elektro'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'elektro'
  union all
  select 'spec', s.id::text, s.key, s.value
  from product_specs s join products p on p.id = s.product_id
  where lower(p.family) = 'elektro';


insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-ELEKTRO-V1', '{"version":"1.0","steps":[{"id":"size","step":1,"title":"Bore","title_sv":"Borrning","title_en":"Bore","required":true,"type":"single_select","options":[{"v":"032","label":"Ø32 mm"},{"v":"050","label":"Ø50 mm"},{"v":"063","label":"Ø63 mm"},{"v":"H63","label":"Ø63 mm Heavy Duty"},{"v":"080","label":"Ø80 mm"},{"v":"100","label":"Ø100 mm"}]},{"id":"stroke_mm","step":2,"title":"Stroke","title_sv":"Slaglängd","title_en":"Stroke","required":true,"type":"numeric","min":8,"max":1500,"unit":"mm"},{"id":"pitch","step":3,"title":"Screw pitch","title_sv":"Skruvstigning","title_en":"Screw pitch","required":true,"type":"single_select","options":[{"v":"1","label":"Stigning 4 mm"},{"v":"2","label":"Stigning 5 mm"},{"v":"4","label":"Stigning 10 mm"},{"v":"5","label":"Stigning 12 mm"},{"v":"6","label":"Stigning 16 mm"},{"v":"7","label":"Stigning 20 mm"},{"v":"8","label":"Stigning 32 mm"},{"v":"9","label":"Stigning 40 mm"}]},{"id":"version","step":4,"title":"Version","title_sv":"Utförande","title_en":"Version","required":true,"type":"single_select","options":[{"v":"1","label":"Direktkopplad, utan vridningsskydd, IP40/IP20"},{"v":"2","label":"Direktkopplad, med vridningsskydd, IP40/IP20"},{"v":"3","label":"Direktkopplad, utan vridningsskydd, IP55/IP65"},{"v":"4","label":"Direktkopplad, med vridningsskydd, IP55/IP65"},{"v":"5","label":"Kuggremsdriven, utan vridningsskydd, IP40/IP20"},{"v":"6","label":"Kuggremsdriven, med vridningsskydd, IP40/IP20"},{"v":"7","label":"Kuggremsdriven, utan vridningsskydd, IP55/IP65"},{"v":"8","label":"Kuggremsdriven, med vridningsskydd, IP55/IP65"}]},{"id":"drive_pack","step":5,"title":"Motor","title_sv":"Motor","title_en":"Motor","required":false,"type":"single_select","options":[{"v":"1110","label":"Stegmotor, fläns NEMA 23, 0,8–1,19 Nm"},{"v":"1120","label":"Stegmotor, fläns NEMA 23, 1,2–2,19 Nm"},{"v":"1121","label":"Stegmotor, fläns NEMA 23, 1,2–2,19 Nm, högre varvtal"},{"v":"1430","label":"Stegmotor, fläns NEMA 34, 2,2–3 Nm"},{"v":"1440","label":"Stegmotor, fläns NEMA 34, 3,01–5 Nm"},{"v":"1450","label":"Stegmotor, fläns NEMA 34, 6,21–7 Nm"},{"v":"1470","label":"Stegmotor, fläns NEMA 34, 7,01–10 Nm"},{"v":"1890","label":"Stegmotor, fläns NEMA 42, 15,01–25 Nm"},{"v":"2200","label":"Borstlös motor, fläns 60, 0–0,79 Nm"},{"v":"220E","label":"Borstlös motor, fläns 60, 0–0,79 Nm, typ E"},{"v":"2220","label":"Borstlös motor, fläns 60, 1,2–2,19 Nm"},{"v":"222E","label":"Borstlös motor, fläns 60, 1,2–2,19 Nm, typ E"},{"v":"2330","label":"Borstlös motor, fläns 80, 2,2–3 Nm"},{"v":"233E","label":"Borstlös motor, fläns 80, 2,2–3 Nm, typ E"},{"v":"2540","label":"Borstlös motor, fläns 86, 3,01–5 Nm"},{"v":"264E","label":"Borstlös motor, fläns 100, 3,01–5 Nm, typ E"},{"v":"2770","label":"Borstlös motor, fläns 130, 7,01–10 Nm"},{"v":"3220","label":"Stegmotor med broms och pulsgivare, fläns 60, 1,2–2,19 Nm"},{"v":"3230","label":"Stegmotor med broms och pulsgivare, fläns 60, 2,2–3 Nm"},{"v":"3430","label":"Stegmotor med broms och pulsgivare, fläns NEMA 34, 2,2–3 Nm"},{"v":"3450","label":"Stegmotor med broms och pulsgivare, fläns NEMA 34, 6,21–7 Nm"},{"v":"3460","label":"Stegmotor med broms och pulsgivare, fläns NEMA 34, 5,01–6,2 Nm"},{"v":"3470","label":"Stegmotor med broms och pulsgivare, fläns NEMA 34, 7,01–10 Nm"},{"v":"4200","label":"Borstlös motor med broms, fläns 60, 0–0,79 Nm"},{"v":"420E","label":"Borstlös motor med broms, fläns 60, 0–0,79 Nm, typ E"},{"v":"4220","label":"Borstlös motor med broms, fläns 60, 1,2–2,19 Nm"},{"v":"422E","label":"Borstlös motor med broms, fläns 60, 1,2–2,19 Nm, typ E"},{"v":"4330","label":"Borstlös motor med broms, fläns 80, 2,2–3 Nm"},{"v":"433E","label":"Borstlös motor med broms, fläns 80, 2,2–3 Nm, typ E"},{"v":"4540","label":"Borstlös motor med broms, fläns 86, 3,01–5 Nm"},{"v":"464E","label":"Borstlös motor med broms, fläns 100, 3,01–5 Nm, typ E"},{"v":"4770","label":"Borstlös motor med broms, fläns 130, 7,01–10 Nm"},{"v":"5120","label":"Stegmotor med broms, utan pulsgivare, fläns NEMA 23, 1,2–2,19 Nm"},{"v":"6770","label":"Borstlös motor med växellåda, fläns 130, 7,01–10 Nm"},{"v":"7770","label":"Borstlös motor med broms och växellåda, fläns 130, 7,01–10 Nm"}]}]}'::jsonb,
        'Metal Work ELEKTRO elcylinder ISO 15552',
        'Metal Work ELEKTRO electric cylinder ISO 15552', 'electric-actuator')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  stroke_min_mm = 8,
  stroke_max_mm = 1500,
  order_code_template = '371{size}{stroke_mm#4}{pitch}{version}{drive_pack}',
  rules_schema_id = 'SCHEMA-ELEKTRO-V1'
where slug = 'elektro';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'elektro';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'elektro';

-- show_code = true: för ELEKTRO ÄR koden det kunden skriver i beställningen.
insert into configurator_params (family_id, param_key, label, param_type, sort_order, required, min_value, max_value, show_code)
select f.id, r.param_key, r.label, r.param_type, r.sort_order, r.required, r.min_value, r.max_value, true
from configurator_families f,
     jsonb_to_recordset('[{"param_key":"size","label":"Borrning","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"stroke_mm","label":"Slaglängd","param_type":"number","sort_order":2,"required":true,"min_value":8,"max_value":1500},{"param_key":"pitch","label":"Skruvstigning","param_type":"select","sort_order":3,"required":true,"min_value":null,"max_value":null},{"param_key":"version","label":"Utförande","param_type":"select","sort_order":4,"required":true,"min_value":null,"max_value":null},{"param_key":"drive_pack","label":"Motor","param_type":"select","sort_order":5,"required":false,"min_value":null,"max_value":null}]'::jsonb)
       as r(param_key text, label text, param_type text, sort_order int, required boolean,
            min_value numeric, max_value numeric)
where f.slug = 'elektro';

