EMA 34, 2,2–3 Nm","sort_order":19},{"param_key":"drive_pack","code":"3450","label":"Stegmotor med broms och pulsgivare, fläns NEMA 34, 6,21–7 Nm","sort_order":20},{"param_key":"drive_pack","code":"3460","label":"Stegmotor med broms och pulsgivare, fläns NEMA 34, 5,01–6,2 Nm","sort_order":21},{"param_key":"drive_pack","code":"3470","label":"Stegmotor med broms och pulsgivare, fläns NEMA 34, 7,01–10 Nm","sort_order":22},{"param_key":"drive_pack","code":"4200","label":"Borstlös motor med broms, fläns 60, 0–0,79 Nm","sort_order":23},{"param_key":"drive_pack","code":"420E","label":"Borstlös motor med broms, fläns 60, 0–0,79 Nm, typ E","sort_order":24},{"param_key":"drive_pack","code":"4220","label":"Borstlös motor med broms, fläns 60, 1,2–2,19 Nm","sort_order":25},{"param_key":"drive_pack","code":"422E","label":"Borstlös motor med broms, fläns 60, 1,2–2,19 Nm, typ E","sort_order":26},{"param_key":"drive_pack","code":"4330","label":"Borstlös motor med broms, fläns 80, 2,2–3 Nm","sort_order":27},{"param_key":"drive_pack","code":"433E","label":"Borstlös motor med broms, fläns 80, 2,2–3 Nm, typ E","sort_order":28},{"param_key":"drive_pack","code":"4540","label":"Borstlös motor med broms, fläns 86, 3,01–5 Nm","sort_order":29},{"param_key":"drive_pack","code":"464E","label":"Borstlös motor med broms, fläns 100, 3,01–5 Nm, typ E","sort_order":30},{"param_key":"drive_pack","code":"4770","label":"Borstlös motor med broms, fläns 130, 7,01–10 Nm","sort_order":31},{"param_key":"drive_pack","code":"5120","label":"Stegmotor med broms, utan pulsgivare, fläns NEMA 23, 1,2–2,19 Nm","sort_order":32},{"param_key":"drive_pack","code":"6770","label":"Borstlös motor med växellåda, fläns 130, 7,01–10 Nm","sort_order":33},{"param_key":"drive_pack","code":"7770","label":"Borstlös motor med broms och växellåda, fläns 130, 7,01–10 Nm","sort_order":34}]'::jsonb)
       as r(param_key text, code text, label text, sort_order int)
join configurator_params p on p.param_key = r.param_key
join configurator_families f on f.id = p.family_id and f.slug = 'elektro';


delete from config_rules where schema_id = 'SCHEMA-ELEKTRO-V1';

insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-ELEKTRO-V1', r.severity, r.if_json, r.message_sv, r.message_en, r.goto_step
